import re

# Simple approach: for search mode, just find non-space tokens
patterns = {
    "default": r'(.+?)',
    "left_simple": r'([^ ]+)',
    "center_simple": r' +([^ ]+) +',
}

texts = [
    " a b c ",
    "text a hello world c more text",
]

for name, pattern in patterns.items():
    print(f"{name}: {pattern!r}")
    compiled = re.compile(pattern)
    for text in texts:
        m = compiled.search(text)
        if m:
            print(f"  search({text!r}) -> group(1)={m.group(1)!r}")
        else:
            print(f"  search({text!r}) -> NO MATCH")
    print()
EOF
